{
  "results": [
    {
      "server": "lambo-dogfood",
      "tools": [
        {
          "tool_name": "lambo-dogfood__lambo_recall",
          "description": "Recall relevant memory for a query and return the Lambo context block (canonical markers, blast-radius warnings, conflict lines).",
          "score": 5.546693325042725,
          "input_schema": {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "additionalProperties": false,
            "properties": {
              "agent_id": {
                "description": "Id of the agent making this call. Caller-asserted and unverified: work\nis recorded under exactly the id you send. Use one stable id per agent —\ncallers sharing an id share its memory attribution and its soft locks.",
                "maxLength": 16384,
                "type": "string"
              },
              "max_tokens": {
                "description": "Token budget for the rendered context block.",
                "format": "uint",
                "maximum": 100000,
                "minimum": 1,
                "type": [
                  "integer",
                  "null"
                ]
              },
              "query": {
                "description": "Natural-language query.",
                "maxLength": 16384,
                "type": "string"
              },
              "top_k": {
                "description": "Hits to return. Defaults to the session config's `default_top_k`.",
                "format": "uint",
                "maximum": 100,
                "minimum": 1,
                "type": [
                  "integer",
                  "null"
                ]
              },
              "traversal_depth": {
                "description": "Graph traversal depth for phase 2 expansion.",
                "format": "uint",
                "maximum": 5,
                "minimum": 0,
                "type": [
                  "integer",
                  "null"
                ]
              }
            },
            "required": [
              "agent_id",
              "query"
            ],
            "type": "object"
          }
        },
        {
          "tool_name": "lambo-dogfood__lambo_saints",
          "description": "List the session's canonical memories — concepts that earned Canonical status through the audited transition path.",
          "score": 1.9510658979415894,
          "input_schema": {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "additionalProperties": false,
            "properties": {
              "agent_id": {
                "description": "Id of the agent making this call. Caller-asserted and unverified: work\nis recorded under exactly the id you send. Use one stable id per agent —\ncallers sharing an id share its memory attribution and its soft locks.",
                "maxLength": 16384,
                "type": "string"
              }
            },
            "required": [
              "agent_id"
            ],
            "type": "object"
          }
        },
        {
          "tool_name": "lambo-dogfood__lambo_inspect",
          "description": "Inspect the neighbourhood around a concept: its type, canonization status, blast radius and typed edges out to a depth.",
          "score": 1.9269647598266602,
          "input_schema": {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "additionalProperties": false,
            "properties": {
              "agent_id": {
                "description": "Id of the agent making this call. Caller-asserted and unverified: work\nis recorded under exactly the id you send. Use one stable id per agent —\ncallers sharing an id share its memory attribution and its soft locks.",
                "maxLength": 16384,
                "type": "string"
              },
              "depth": {
                "description": "Hops out from the focus (default 2, max 5).",
                "format": "uint",
                "maximum": 5,
                "minimum": 0,
                "type": [
                  "integer",
                  "null"
                ]
              },
              "focus": {
                "description": "Concept content (or a node UUID) to centre the neighbourhood on.",
                "maxLength": 16384,
                "type": "string"
              }
            },
            "required": [
              "agent_id",
              "focus"
            ],
            "type": "object"
          }
        },
        {
          "tool_name": "lambo-dogfood__lambo_reserve",
          "description": "Take a soft lock on a memory node before editing it (or release one). Reservations are advisory and do not survive a server restart. The lock is held under the agent_id you send, which is caller-asserted and unverified: a distinct id gets a distinct lock, and callers sharing an id share the lock.",
          "score": 1.8276288509368896,
          "input_schema": {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "additionalProperties": false,
            "properties": {
              "agent_id": {
                "description": "Id of the agent making this call — the identity the lock is held under.\nCaller-asserted and unverified: locks are cooperative. A distinct id\ngets a distinct lock; two callers sending the SAME id share one lock and\ncan release each other's. Use one stable id per agent.",
                "maxLength": 16384,
                "type": "string"
              },
              "node_id": {
                "description": "Node to reserve, as a UUID string (from `lambo_recall` or\n`lambo_inspect`).",
                "maxLength": 16384,
                "type": "string"
              },
              "release": {
                "description": "Release this agent's existing soft lock instead of taking one.",
                "type": [
                  "boolean",
                  "null"
                ]
              },
              "ttl_seconds": {
                "description": "Soft-lock lifetime in seconds (default 30, max 3600).",
                "format": "uint64",
                "maximum": 3600,
                "minimum": 1,
                "type": [
                  "integer",
                  "null"
                ]
              }
            },
            "required": [
              "agent_id",
              "node_id"
            ],
            "type": "object"
          }
        },
        {
          "tool_name": "lambo-dogfood__lambo_stats",
          "description": "Session health: flush lag, write-behind log depth, background write queue depth, node/edge/concept counts, canonization progress and degraded state. Pass a receipt from a lambo_derive or lambo_record_action ack to ask what happened to that one write, and wait_ms to wait for it to be applied first.",
          "score": 1.8276288509368896,
          "input_schema": {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "additionalProperties": false,
            "properties": {
              "agent_id": {
                "description": "Id of the agent making this call. Caller-asserted and unverified: work\nis recorded under exactly the id you send. Use one stable id per agent —\ncallers sharing an id share its memory attribution and its soft locks.",
                "maxLength": 16384,
                "type": "string"
              },
              "receipt": {
                "description": "A write receipt id from a `lambo_derive` or `lambo_record_action` ack.\nAnswers what happened to that one write: applied, failed, dropped,\npending, expired, restart-lost or never-issued. Receipts are scoped to\nthe agent that created them.",
                "maxLength": 16384,
                "type": [
                  "string",
                  "null"
                ]
              },
              "wait_ms": {
                "description": "With `receipt`, wait up to this many milliseconds for the write to be\napplied before answering — the opt-in synchrony that restores\nread-your-writes when you need it. Clamped to the server's own maximum.\nIgnored without `receipt`.\n\nThe published maximum is [`crate::writeq::RECEIPT_WAIT_MAX`] in\nmilliseconds — a client that sends more is clamped to it rather than\nrefused, and `the_published_wait_maximum_is_the_real_one` pins the\nliteral below to the constant (T88-H4 requires a *published* maximum,\nand `schemars` takes a literal).",
                "format": "uint64",
                "maximum": 4000,
                "minimum": 0,
                "type": [
                  "integer",
                  "null"
                ]
              }
            },
            "required": [
              "agent_id"
            ],
            "type": "object"
          }
        },
        {
          "tool_name": "lambo-dogfood__lambo_record_action",
          "description": "Record an action the agent took, with what it produces, modifies and depends on. created_at is stamped server-side. event_time is optional RFC3339 historical about-time, such as a commit or document date; omit it for a live fact, which is about now. Returns as soon as the input is validated and ordered — the write is applied in the background and the ack carries a receipt id, resolved the same way as lambo_derive's.",
          "score": 1.7817050218582153,
          "input_schema": {
            "$defs": {
              "WireResource": {
                "description": "One entry in a `lambo_record_action` resource list (`produces`,\n`modifies`, `depends_on`). A plain string on the wire, with the same\nper-string size cap the runtime enforces, so a client can pre-validate an\nentry without a round trip.",
                "maxLength": 16384,
                "type": "string"
              }
            },
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "additionalProperties": false,
            "properties": {
              "action": {
                "description": "The action taken — becomes a `Resource` concept.",
                "maxLength": 16384,
                "type": "string"
              },
              "agent_id": {
                "description": "Id of the agent making this call. Caller-asserted and unverified: work\nis recorded under exactly the id you send. Use one stable id per agent —\ncallers sharing an id share its memory attribution and its soft locks.",
                "maxLength": 16384,
                "type": "string"
              },
              "depends_on": {
                "description": "Things this action depends on (`Dependency` edges).",
                "items": {
                  "$ref": "#/$defs/WireResource"
                },
                "type": [
                  "array",
                  "null"
                ]
              },
              "event_time": {
                "description": "Optional RFC3339 historical about-time for this evidence, such as a\ncommit or document date. Omit it for a live fact, which is about now.\nNo additional date-range bounds are applied.",
                "format": "date-time",
                "maxLength": 16384,
                "type": [
                  "string",
                  "null"
                ]
              },
              "modifies": {
                "description": "Resources this action mutates (`Causal` edges).",
                "items": {
                  "$ref": "#/$defs/WireResource"
                },
                "type": [
                  "array",
                  "null"
                ]
              },
              "produces": {
                "description": "Resources this action creates (`Causal` edges).",
                "items": {
                  "$ref": "#/$defs/WireResource"
                },
                "type": [
                  "array",
                  "null"
                ]
              }
            },
            "required": [
              "agent_id",
              "action"
            ],
            "type": "object"
          }
        },
        {
          "tool_name": "lambo-dogfood__lambo_derive",
          "description": "Derive concepts from the current interaction into session memory. created_at is stamped server-side. event_time is optional RFC3339 historical about-time, such as a commit or document date; omit it for a live fact, which is about now. Returns as soon as the input is validated and ordered — the write is applied in the background and the ack carries a receipt id. The outcome is piggybacked on your next tool response; to wait for it, call lambo_stats with that receipt and a wait_ms.",
          "score": 1.777644395828247,
          "input_schema": {
            "$defs": {
              "WireConcept": {
                "additionalProperties": false,
                "properties": {
                  "concept_type": {
                    "$ref": "#/$defs/WireConceptType",
                    "description": "One of `entity`, `logic`, `constraint`, `resource`, `observation`."
                  },
                  "content": {
                    "description": "The concept text.",
                    "maxLength": 16384,
                    "type": "string"
                  }
                },
                "required": [
                  "content",
                  "concept_type"
                ],
                "type": "object"
              },
              "WireConceptType": {
                "description": "What kind of thing a concept is. Pick the one that fits the content best:\n\n- `entity` — a named thing: a person, service, file, table, or component.\n- `logic` — a rule, decision, or piece of reasoning about how things work.\n- `constraint` — a requirement or limit that must keep holding.\n- `resource` — something produced, consumed, or acted on by the work.\n- `observation` — something noticed in passing; the weakest, most\n  evictable kind, and the only one that can later be demoted.",
                "enum": [
                  "entity",
                  "logic",
                  "constraint",
                  "resource",
                  "observation"
                ],
                "type": "string"
              },
              "WireParentOf": {
                "additionalProperties": false,
                "properties": {
                  "child": {
                    "maxLength": 16384,
                    "type": "string"
                  },
                  "parent": {
                    "maxLength": 16384,
                    "type": "string"
                  }
                },
                "required": [
                  "parent",
                  "child"
                ],
                "type": "object"
              }
            },
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "additionalProperties": false,
            "properties": {
              "agent_id": {
                "description": "Id of the agent making this call. Caller-asserted and unverified: work\nis recorded under exactly the id you send. Use one stable id per agent —\ncallers sharing an id share its memory attribution and its soft locks.",
                "maxLength": 16384,
                "type": "string"
              },
              "concepts": {
                "description": "Concepts to derive from this interaction.",
                "items": {
                  "$ref": "#/$defs/WireConcept"
                },
                "type": "array"
              },
              "event_time": {
                "description": "Optional RFC3339 historical about-time for this evidence, such as a\ncommit or document date. Omit it for a live fact, which is about now.\nNo additional date-range bounds are applied.",
                "format": "date-time",
                "maxLength": 16384,
                "type": [
                  "string",
                  "null"
                ]
              },
              "parent_of": {
                "description": "Optional `(parent, child)` hierarchy pairs. Both ends resolve (and may\nbe created) as concepts.",
                "items": {
                  "$ref": "#/$defs/WireParentOf"
                },
                "type": [
                  "array",
                  "null"
                ]
              }
            },
            "required": [
              "agent_id",
              "concepts"
            ],
            "type": "object"
          }
        }
      ]
    },
    {
      "server": "donsetch",
      "tools": [
        {
          "tool_name": "donsetch__web_search",
          "description": "Web search : returns ranked URLs + titles + snippets. Use to decide WHAT to fetch (web_fetch reads content; this never does).\n\nOne query is the normal path. For an ambiguous, multilingual, exploratory, or hard-to-recall information need, add up to two query_variants: all searches run in parallel and come back as clearly separated result sets, with no automatic rewriting or guessed answers.\n\nResults list random handles: each result shows an S-handle (fetch the S-handle shown next to a result; raw URLs in structuredContent for citation). Domains known to need the browser carry a ⚠ needs-browser hint : pick a faster source or budget time before fetching. A *degraded:* footer names any engines that failed : silent quality loss is visible.\n\nEngines: 10+ keyless backends fused by cross-engine consensus + local semantic reranking (automatic). Verticals via intent: GitHub, Wikipedia, HN, Scholar, news, StackExchange, MDN. BYOK: providers configured via `donsetch keys` (Tavily/Exa/Serper/TinyFish/Parallel/BrightData) take over; structuredContent.provider names what served (null = local keyless).\n\ndeadline_ms caps the whole call (honest deadline error, never a hang).\n\nSingle-query response: numbered markdown list and structuredContent = {intent, weak, cached, elapsed_ms, provider, results:[...], engines:[...]}. Multi-query response: one Search section per query and structuredContent = {query_count, ok, errors, elapsed_ms, searches:[{query, ...single-query fields}]}. Key signals: weak=true = low consensus, treat with care; consensus = independent engines agreeing (authority); engines[].status = per-engine health.\n\nAfter search: fetch the best result via its S-handle : enrichment pre-fetches top results, so the next fetch is near-instant (prewarmed_by_search=true)",
          "score": 1.4755239486694336,
          "input_schema": {
            "properties": {
              "deadline_ms": {
                "description": "Hard time budget in ms (500-600000). Engines have their own timeouts; this caps the whole call. On expiry: honest deadline error.",
                "type": "integer"
              },
              "intent": {
                "description": "auto (default) detects from query. code: adds GitHub, HN, StackExchange, MDN verticals. paper: adds Scholar, arXiv. news: adds Google News, HN. entity: adds Wikipedia. web: general only.",
                "enum": [
                  "auto",
                  "web",
                  "code",
                  "paper",
                  "news",
                  "entity"
                ],
                "type": "string"
              },
              "max_results": {
                "description": "Max results (default 7, max 12). The most relevant results almost always live in the top 7. Increase only when results are weak.",
                "type": "integer"
              },
              "query": {
                "description": "Search query.",
                "type": "string"
              },
              "query_variants": {
                "description": "Optional alternate formulations of the same information need (max 2). DonSeTch searches the base query and variants in parallel and returns one clearly separated result set per query. Use for ambiguous, multilingual, exploratory, or hard-to-recall searches; never put a guessed answer in a variant.",
                "items": {
                  "type": "string"
                },
                "maxItems": 2,
                "type": "array"
              }
            },
            "required": [
              "query"
            ],
            "type": "object"
          }
        }
      ]
    }
  ],
  "total_hidden_tools": 20,
  "status": "ready",
  "note": null
}

